<?php
require_once __DIR__ . '/config/conexion.php';
require_login();
$q=trim($_GET['q']??'');$fecha=trim($_GET['fecha']??'');$estado=$_GET['estado']??'';$sql="SELECT p.*,u.nombre usuario,l.titulo libro,IF(p.estado_prestamo='Activo' AND p.fecha_devolucion<CURDATE(),'Atrasado',p.estado_prestamo) estado_vista FROM prestamos p JOIN usuarios u ON u.id_usuario=p.id_usuario JOIN libros l ON l.id_libro=p.id_libro WHERE 1=1";$params=[];
if($q!==''){$sql.=' AND (u.nombre LIKE ? OR l.titulo LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}if($fecha!==''&&valid_date($fecha)){$sql.=' AND (p.fecha_prestamo=? OR p.fecha_devolucion=?)';$params[]=$fecha;$params[]=$fecha;}if($estado==='Activo')$sql.=" AND p.estado_prestamo='Activo'";elseif($estado==='Devuelto')$sql.=" AND p.estado_prestamo='Devuelto'";elseif($estado==='Atrasado')$sql.=" AND p.estado_prestamo='Activo' AND p.fecha_devolucion<CURDATE()";$sql.=' ORDER BY p.id_prestamo DESC';$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();page_start('Historial','historial.php');
?>
<div class="page-heading"><div><span class="eyebrow">REGISTROS</span><h1>Historial</h1><p>Consulta préstamos activos y devueltos.</p></div></div><section class="panel"><form method="get" class="row g-2 mb-3"><div class="col-md-5"><input class="form-control" name="q" placeholder="Buscar usuario o libro" value="<?= e($q); ?>"></div><div class="col-md-3"><input class="form-control" type="date" name="fecha" value="<?= e($fecha); ?>"></div><div class="col-md-2"><select class="form-select" name="estado"><option value="">Todos</option><?php foreach(['Activo','Devuelto','Atrasado'] as $s): ?><option value="<?= e($s); ?>" <?= $estado===$s?'selected':''; ?>><?= e($s); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-outline-primary">Filtrar</button></div></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Usuario</th><th>Libro</th><th>Préstamo</th><th>Devolución</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $p): ?><tr><td><?= e($p['usuario']); ?></td><td><?= e($p['libro']); ?></td><td><?= e($p['fecha_prestamo']); ?></td><td><?= e($p['fecha_devolucion']); ?></td><td><span class="badge rounded-pill text-bg-<?= $p['estado_vista']==='Atrasado'?'danger':($p['estado_vista']==='Devuelto'?'success':'warning'); ?>"><?= e($p['estado_vista']); ?></span></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="text-center text-secondary py-4">No se encontraron préstamos.</td></tr><?php endif; ?></tbody></table></div></section><?php page_end(); ?>
